   206    unsigned int bucket_for (K key) const
   207    {
   208      unsigned int i = hb_hash (key) % prime;
   209      unsigned int step = 0;
   210      unsigned int tombstone = (unsigned) -1;
   211      while (!items[i].is_unused ())
   212      {
   213        if (items[i] == key)
   214          return i;
   215        if (tombstone == (unsigned) -1 && items[i].is_tombstone ())
   216          tombstone = i;
   217        i = (i + ++step) & mask;
   218      }
   219      return tombstone == (unsigned) -1 ? i : tombstone;
   220    }
